    def __init__(self,x,/,*,y=3):
        self.x=x+y
a=A(4,y=5)
print(a.x)

class A:
    def __init__(self):
        return 1
A()

class A: pass
class B(A,A):
    print("body")

A=7
try:
    class A:
        print("body")
        1//0
except ZeroDivisionError:
    print(A)

events=[]
class A: pass
def base(n):
    events.append(n)
    return A
try:
    class B(base(1),base(2)):
        events.append(3)
except TypeError:
    print(events[0],events[1],events[2])

class A: pass
a=A()
try:
    a.missing
except AttributeError:
    print("get")
try:
    del a.missing
except AttributeError:
    print("del")

class D:
    def __get__(self,obj,owner): return 7
class A:
    x=D()
print(A().x)

events=[]
def decorate(cls):
    events.append(2)
    return cls
@decorate
class A:
    events.append(1)
print(events[0],events[1])

class A:
    def __len__(self): return 3
print(len(A()))

x=8
class Outer:
    x=1
    class Inner:
        y=x
print(Outer.Inner.y,Outer.Inner.__qualname__,Outer.__qualname__)

types=[]
for n in (1,2):
    class A:
        x=n
    types.append(A)
print(types[0] is types[1],types[0].x,types[1].x)

class A:
    total=0
    for n in (1,2,3):
        total+=n
print(A.total,A.n)

class A:
    __module__="custom"
print(A.__module__)

class A:
    def f(self): return __class__
print(A().f() is A)
